 * `target` 是科目 slug，要定位到**哪个节点**的实验目录得再给一个 `{ number }`。
 * 绝大多数域不看它——不看就忽略，参数是可选的一路加在最后。
 */
export type DomainLoader = (domain: Domain, target?: string, options?: unknown) => unknown;

export interface DomainAccess {
